  border-radius: 999px;
  background: rgba(255, 255, 255, 0.92);
  color: #64748b;
  cursor: pointer;
  transform: translateY(-50%);
}

.assis-product-detail-nav svg {
  width: 12px;
  height: 12px;
}

.assis-product-detail-nav--prev {
  inset-inline-start: 18px;
}

.assis-product-detail-nav--next {
  inset-inline-end: 18px;
}

.assis-product-detail-copy {
  display: flex;
  flex-direction: column;
  gap: 8px;
  flex: 1 1 auto;
  min-height: 0;
  overflow-y: auto;
  padding: 12px 14px 10px;
}

.assis-product-detail-copy > * {
  flex-shrink: 0;
}

.assis-product-detail-title-row {
  display: flex;
  align-items: center;
  gap: 6px;
  direction: ltr;
}

.assis-product-detail-main[dir="rtl"] .assis-product-detail-title-row {
  justify-content: flex-end;
}

.assis-product-detail-title-link {
  appearance: none;
  display: flex;
  align-items: center;
  justify-content: center;
  flex: 0 0 auto;
  width: 22px;
  height: 22px;
  padding: 0;
  border: none;
  background: transparent;
  color: #1d6fee;
  cursor: pointer;
}

.assis-product-detail-title-link svg {
  width: 18px;
  height: 18px;
}

.assis-product-detail-title-link:hover {
  color: #1557c0;
}

.assis-product-detail-title {
  margin: 0;
  flex: 1 1 auto;
  min-width: 0;
  font-size: 16px;
  font-weight: 650;
  line-height: 1.3;
  color: #0f172a;
  text-align: start;
}

.assis-product-detail-title--link {
  cursor: pointer;
}

.assis-product-detail-title--link:hover {
  color: #1d6fee;
}

.assis-product-detail-main[dir="rtl"] .assis-product-detail-title {
  flex: 0 1 auto;
}

.assis-product-detail-rating {
  display: flex;
  align-items: center;
  justify-content: flex-start;
  gap: 5px;
  color: #64748b;
  font-size: 12px;
  line-height: 1;
}

.assis-product-detail-stars {
  display: inline-flex;
  gap: 1px;
}

.assis-product-detail-star {
  position: relative;
  width: 13px;
  height: 13px;
}

.assis-product-detail-star svg {
  position: absolute;
  inset: 0;
  width: 13px;
  height: 13px;
  fill: #e7e1d6;
}

.assis-product-detail-star svg.is-on {
  fill: #e0a106;
}

.assis-product-detail-score {
  color: #0f172a;
  font-weight: 650;
}

.assis-product-detail-count {
  color: #94a3b8;
}

.assis-product-detail-price-block {
  display: flex;
  flex-direction: column;
  align-items: flex-start;
  gap: 6px;
  min-width: 0;
}

.assis-product-detail-price-row {
  display: flex;
  flex-wrap: wrap;
  align-items: baseline;
  justify-content: flex-start;
  gap: 8px 12px;
  min-width: 0;
}

.assis-product-detail-price-region {
  min-width: 2.6em;
  font-size: 12px;
  font-weight: 550;
  color: #94a3b8;
}

.assis-product-detail-price-value {
  font-size: 16px;
  font-weight: 650;
  color: #0f172a;
  line-height: 1.3;
}

.assis-product-detail-price-club {
  display: inline-flex;
  align-items: baseline;
  gap: 5px;
  padding: 2px 8px;
  border-radius: 999px;
  background: rgba(29, 111, 238, 0.08);
  line-height: 1.3;
}

.assis-product-detail-price-club-label {
  font-size: 11px;
  font-weight: 550;
  color: #1d6fee;
}

.assis-product-detail-price-club-value {
  font-size: 13px;
  font-weight: 650;
  color: #1d6fee;
}

.assis-product-detail-was {
  color: #94a3b8;
  font-size: 12px;
  text-decoration: line-through;
}

.assis-product-detail-off {
  padding: 2px 7px;
  border-radius: 4px;
  background: rgba(29, 111, 238, 0.12);
  color: #1d6fee;
  font-size: 11px;
  font-weight: 650;
}

.assis-product-detail-options {
  display: flex;
  flex-direction: column;
  gap: 10px;
  width: 100%;
}

.assis-product-detail-option-group {
  display: flex;
  flex-direction: column;
  align-items: flex-start;
  gap: 6px;
  width: 100%;
  min-width: 0;
}

.assis-product-detail-option-name {
  color: #64748b;
  font-size: 12px;
  font-weight: 650;
}

.assis-product-detail-swatches {
  display: grid;
  grid-template-columns: repeat(4, minmax(0, 1fr));
  gap: 6px;
  width: 100%;
}

.assis-product-detail-swatch {
  appearance: none;
  aspect-ratio: 1;
  padding: 0;
  border: 1px solid rgba(15, 23, 42, 0.12);
  border-radius: 10px;
  overflow: hidden;
  background: #f8fafc;
  color: #334155;
  font-size: 10px;
  font-family: inherit;
  cursor: pointer;
}

.assis-product-detail-swatch img {
  display: block;
  width: 100%;
  height: 100%;
  object-fit: cover;
}

.assis-product-detail-swatch span {
  display: flex;
  align-items: center;
  justify-content: center;
  width: 100%;
  height: 100%;
  padding: 4px;
  text-align: center;
}

.assis-product-detail-swatch.is-on {
  border-color: #1d6fee;
  box-shadow: 0 0 0 1px #1d6fee;
}

.assis-product-detail-swatch.is-off,
.assis-product-detail-swatch:disabled {
  opacity: 0.4;
  cursor: default;
}

.assis-product-detail-pills {
  display: flex;
  flex-wrap: wrap;
  gap: 6px;
  width: 100%;
}

.assis-product-detail-variant {
  appearance: none;
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 8px;
  width: 100%;
  min-width: 0;
  height: 34px;
  padding: 0 12px;
  border: 1px solid rgba(15, 23, 42, 0.1);
  border-radius: 10px;
  background: #ffffff;
  color: #0f172a;
  font-size: 12px;
  font-family: inherit;
  text-align: start;
  cursor: pointer;
  box-shadow: 0 2px 6px rgba(15, 23, 42, 0.06);
}

.assis-product-detail-variant span {
  min-width: 0;
  overflow: hidden;
  white-space: nowrap;
  text-overflow: ellipsis;
}

.assis-product-detail-variant svg {
  width: 14px;
  height: 14px;
  flex-shrink: 0;
  color: #64748b;
}

.assis-product-detail-option {
  appearance: none;
  max-width: 100%;
  padding: 5px 10px;
  border: 1px solid rgba(15, 23, 42, 0.08);
  border-radius: 999px;
  background: #ffffff;
  color: #334155;
  font-size: 12px;
  font-family: inherit;
  cursor: pointer;
}

.assis-product-detail-option.is-selected {
  border-color: #1d6fee;
  color: #1d6fee;
  background: rgba(29, 111, 238, 0.08);
}

.assis-product-detail-option:disabled {
  opacity: 0.4;
  cursor: default;
}

.assis-product-detail-desc-block {
  display: flex;
  flex-direction: column;
  align-items: flex-start;
  gap: 2px;
  min-width: 0;
}

.assis-product-detail-desc {
  display: -webkit-box;
  margin: 0;
  overflow: hidden;
  color: #64748b;
  font-size: 12px;
  line-height: 1.45;
  -webkit-box-orient: vertical;
  -webkit-line-clamp: 4;
}

.assis-product-detail-desc.is-open {
  display: block;
  overflow: visible;
  -webkit-line-clamp: unset;
}

.assis-product-detail-desc-more {
  appearance: none;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  width: 22px;
  height: 16px;
  margin: 0;
  padding: 0;
  border: none;
  background: transparent;
  color: #64748b;
  cursor: pointer;
}

.assis-product-detail-desc-more svg {
  width: 14px;
  height: 14px;
}

.assis-product-detail-desc-more.is-open svg {
  transform: rotate(180deg);
}

.assis-product-detail-ask {
  display: flex;
  flex-direction: column;
  gap: 8px;
  margin-top: 8px;
  padding: 10px;
  border-radius: 16px;
  background: #f4f7ff;
}

.assis-product-detail-ask-title {
  display: flex;
  align-items: center;
  gap: 6px;
  color: #0f172a;
  font-size: 12px;
  font-weight: 650;
}

.assis-product-detail-ask-heart {
  width: 16px;
  height: 16px;
  flex-shrink: 0;
}

.assis-product-detail-questions {
  display: flex;
  flex-direction: column;
  gap: 6px;
}

.assis-product-detail-question {
  appearance: none;
  display: inline-flex;
  align-items: center;
  justify-content: flex-start;
  gap: 6px;
  width: 100%;
  min-width: 0;
  padding: 8px 10px;
  border: 1px solid rgba(15, 23, 42, 0.06);
  border-radius: 999px;
  background: #ffffff;
  color: #334155;
  font-size: 12px;
  font-family: inherit;
  line-height: 1.3;
  text-align: start;
  cursor: pointer;
}

.assis-product-detail-question svg {
  width: 12px;
  height: 12px;
  flex-shrink: 0;
}

.assis-product-detail-question span {
  min-width: 0;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.assis-product-detail-question,
.assis-product-detail-foot-question,
.assis-product-detail-option {
  box-shadow: 0 4px 12px rgba(15, 23, 42, 0.07);
  transition: transform 0.18s ease, box-shadow 0.18s ease;
}

.assis-product-detail-question:hover,
.assis-product-detail-foot-question:hover,
.assis-product-detail-option:hover {
  transform: translateY(-1px);
  box-shadow: 0 8px 16px rgba(15, 23, 42, 0.12);
}

.assis-product-detail-question:active,
.assis-product-detail-foot-question:active,
.assis-product-detail-option:active {
  transform: scale(0.98);
}

.assis-product-detail-foot {
  position: absolute;
  right: 0;
  bottom: 0;
  left: 0;
  z-index: 5;
  display: flex;
  align-items: center;
  flex-wrap: nowrap;
  gap: 8px;
  width: auto;
  padding: 10px 14px 14px;
  border-top: 1px solid rgba(15, 23, 42, 0.06);
  border-radius: 0 0 18px 18px;
  background: #ffffff;
  pointer-events: auto;
}

.chat-container.assis-chat-he-flip .assis-product-detail-foot {
  flex-direction: row-reverse;
}

.assis-product-detail-qty {
  display: flex;
  direction: ltr;
  align-items: center;
  gap: 2px;
  flex: 0 0 auto;
  padding: 3px;
  border-radius: 999px;
  background: #eef1f4;
  box-shadow: inset 0 0 0 1px rgba(15, 23, 42, 0.04);
}

.assis-product-detail-qty button {
  appearance: none;
  display: flex;
  align-items: center;
  justify-content: center;
  width: 26px;
  height: 26px;
  padding: 0;
  border: none;
  border-radius: 999px;
  background: #ffffff;
  color: #1e293b;
  box-shadow: 0 2px 6px rgba(15, 23, 42, 0.1);
  cursor: pointer;
  transition: transform 0.16s ease, box-shadow 0.16s ease;
}

.assis-product-detail-qty button:hover:not(:disabled) {
  transform: translateY(-1px);
  box-shadow: 0 5px 10px rgba(15, 23, 42, 0.14);
}

.assis-product-detail-qty button:active:not(:disabled) {
  transform: scale(0.94);
}

.assis-product-detail-qty button svg {
  width: 13px;
  height: 13px;
}

.assis-product-detail-qty button:disabled {
  opacity: 0.35;
  cursor: default;
  box-shadow: none;
}

.assis-product-detail-qty span {
  display: flex;
  align-items: center;
  justify-content: center;
  width: 22px;
  height: 26px;
  border-radius: 999px;
  background: transparent;
  box-shadow: none;
  color: #0f172a;
  font-size: 13px;
  font-weight: 650;
  text-align: center;
}

.assis-product-detail-foot-question {
  appearance: none;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 5px;
  flex: 1 1 auto;
  min-width: 0;
  height: 32px;
  padding: 0 10px;
  border: 1px solid rgba(29, 111, 238, 0.18);
  border-radius: 999px;
  background: rgba(29, 111, 238, 0.08);
  color: #1d6fee;
  font-size: 12px;
  font-family: inherit;
  cursor: pointer;
}

.assis-product-detail-foot-question svg {
  width: 12px;
  height: 12px;
  flex-shrink: 0;
}

.assis-product-detail-foot-question span {
  min-width: 0;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.assis-product-detail-add {
  appearance: none;
  position: relative;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 6px;
  flex: 1 1 auto;
  min-width: 0;
  height: 36px;
  padding: 0 14px;
  border: none;
  border-radius: 999px;
  background-color: #1d6fee;
  background-image: linear-gradient(110deg, #1557c0 0%, #1d6fee 42%, #1d6fee 47%, rgba(255, 255, 255, 0.55) 50%, #1d6fee 53%, #1d6fee 58%, #134bab 100%);
  background-size: 220% 100%;
  color: #ffffff;
  font-size: 13px;
  font-weight: 550;
  font-family: inherit;
  line-height: 1;
  white-space: nowrap;
  box-shadow: 0 8px 18px rgba(29, 111, 238, 0.32);
  cursor: pointer;
  animation: assis-product-add-sheen 3.4s ease-in-out infinite;
  transition: transform 0.18s ease, box-shadow 0.18s ease;
}

@keyframes assis-product-add-sheen {
  0% { background-position: 100% 0; }
  100% { background-position: 0% 0; }
}

.assis-product-detail-add.has-total {
  justify-content: space-between;
  padding: 0 14px 0 16px;
}

.assis-product-detail-add-label {
  display: inline-flex;
  align-items: center;
  gap: 6px;
  min-width: 0;
}

.assis-product-detail-add svg {
  width: 16px;
  height: 16px;
  flex-shrink: 0;
}

.assis-product-detail-add-total {
  flex-shrink: 0;
  font-weight: 650;
}

.chat-container.assis-chat-he-flip .assis-product-detail-add.has-total {
  direction: ltr;
  display: grid;
  grid-template-columns: minmax(0, 1fr) auto minmax(0, 1fr);
  align-items: center;
  justify-content: stretch;
  padding: 0 14px;
}

.chat-container.assis-chat-he-flip .assis-product-detail-add.has-total .assis-product-detail-add-total {
  grid-column: 1;
  grid-row: 1;
  justify-self: start;
  line-height: 1;
}

.chat-container.assis-chat-he-flip .assis-product-detail-add.has-total .assis-product-detail-add-label {
  grid-column: 2;
  grid-row: 1;
  justify-self: center;
  line-height: 1;
}

.assis-product-detail-add span {
  color: #ffffff;
  white-space: nowrap;
}

.assis-product-detail-add:disabled {
  opacity: 0.45;
  cursor: default;
}

.assis-product-detail-add:hover:not(:disabled) {
  transform: translateY(-1px);
  box-shadow: 0 12px 22px rgba(29, 111, 238, 0.4);
}

.assis-product-detail-add:active:not(:disabled) {
  transform: scale(0.98);
}

@media (prefers-reduced-motion: reduce) {
  .assis-product-detail-add {
    animation: none;
  }
}

.chat-container {
  position: fixed;
  bottom: 120px;
  right: 30px;
  width: 343px;
  max-width: calc(100vw - 60px);
  background: white;
  border-radius: 24px;
  box-shadow: 0 10px 24px rgba(148, 163, 184, 0.16), 0 2px 6px rgba(15, 23, 42, 0.04);
  overflow: hidden;
  z-index: 999;
  height: 640px;
  max-height: 80dvh;
  display: flex;
  flex-direction: column;

  &.chat-container-small {
    bottom: 108px;
  }
  &.chat-container-medium {
    bottom: 120px;
  }
  &.chat-container-large {
    bottom: 124px;
  }
}

.chat-container.assis-home-open {
  width: min(500px, calc(100vw - 40px));
  height: min(420px, calc(100dvh - 100px));
  max-width: calc(100vw - 40px);
  bottom: 20px;
  border-radius: 28px;
  overflow: visible;
  background:
    radial-gradient(ellipse 65% 55% at 82% 38%, rgba(29, 111, 238, 0.22), transparent 70%),
    radial-gradient(ellipse 50% 40% at 20% 82%, rgba(29, 111, 238, 0.08), transparent 65%),
    #ffffff;
}

/* Belt-and-suspenders: never paint conversation under the home shell (reset race). */
.chat-container.assis-home-open > .chat-content {
  display: none !important;
}

.chat-container.assis-chat-v2 {
  width: min(500px, calc(100vw - 40px));
  height: min(420px, calc(100dvh - 100px));
  max-width: calc(100vw - 40px);
  bottom: 20px;
  border-radius: 28px;
  background:
    radial-gradient(ellipse 72% 58% at 92% 8%, rgba(29, 111, 238, 0.13), transparent 68%),
    radial-gradient(ellipse 58% 48% at 6% 92%, rgba(29, 111, 238, 0.07), transparent 64%),
    linear-gradient(180deg, #f8fbff 0%, #ffffff 46%, #f3f8ff 100%);
}

.chat-container.assis-home-open.chat-maximized,
.chat-container.assis-chat-v2.chat-maximized {
  width: min(800px, calc(100vw - 40px));
  height: min(580px, calc(100dvh - 40px));
}

.chat-container.assis-home-open .chat-header,
.chat-container.assis-chat-v2 .chat-header {
  border-bottom: none;
  background: transparent;
  height: auto;
  min-height: 44px;
  padding: 10px 14px 8px;
  gap: 8px;
  position: relative;
  overflow: visible;
  justify-content: flex-start;
  direction: ltr;
}

.chat-container.assis-chat-v2 .chat-header--with-promo {
  display: grid;
  /* Compact chat (~343px): keep brand + actions usable; promo stays small. */
  grid-template-columns: minmax(72px, 1fr) minmax(0, 140px) minmax(108px, 1fr);
  align-items: center;
  column-gap: 6px;
  position: relative;
}

.chat-container.assis-chat-v2.chat-maximized .chat-header--with-promo {
  /* Large / maximized chat: more room for Summary. */
  grid-template-columns: minmax(120px, 1fr) minmax(0, 340px) minmax(120px, 1fr);
  column-gap: 8px;
}

.chat-container.assis-home-open .header-content.header-brand,
.chat-container.assis-chat-v2 .header-content.header-brand {
  display: inline-flex;
  flex-direction: row;
  align-items: center;
  gap: 8px;
  min-width: 0;
  max-width: min(280px, calc(100% - 88px));
  margin: 0;
  padding: 0;
  order: 0;
  flex: 0 1 auto;
  overflow: hidden;
  pointer-events: none;
  position: relative;
  z-index: 45;
  direction: ltr;
}

.chat-container.assis-chat-v2 .chat-header--with-promo .header-content.header-brand {
  grid-column: 1;
  justify-self: start;
  width: 100%;
  max-width: 100%;
  min-width: 0;
}

.chat-container.assis-home-open .header-content.header-brand img,
.chat-container.assis-chat-v2 .header-content.header-brand img {
  width: 22px;
  height: 22px;
  object-fit: cover;
  border-radius: 6px;
  flex-shrink: 0;
  background: #fff;
}

.chat-container.assis-home-open .header-content.header-brand span,
.chat-container.assis-chat-v2 .header-content.header-brand span {
  min-width: 0;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
  font-size: 12.5px;
  font-weight: 500;
  letter-spacing: 0.01em;
  color: #2f3640;
  line-height: 1.2;
}

.chat-container.assis-chat-v2 .header-actions > button,
.chat-container.assis-chat-v2 .header-menu-wrapper > button,
.chat-container.assis-chat-v2 #assis-furisport-cart-btn {
  width: 26px;
  height: 26px;
  border-radius: 999px;
  background: rgba(255, 255, 255, 0.72);
  border: none;
  box-shadow: 0 0 0 1px rgba(0, 0, 0, 0.05);
  color: #7a8490;
}

.chat-container.assis-chat-v2 .header-actions > button svg,
.chat-container.assis-chat-v2 .header-menu-wrapper > button svg,
.chat-container.assis-chat-v2 #assis-furisport-cart-btn svg {
  display: block;
  width: 12px;
  height: 12px;
  flex-shrink: 0;
  overflow: visible;
}

.chat-container.assis-chat-v2 .header-menu-wrapper > button svg.menu-btn-icon {
  fill: currentColor;
  stroke: none;
}

.chat-container.assis-chat-v2 #assis-furisport-cart-btn svg {
  width: 16px;
  height: 16px;
}

.assis-plugin-root .assis-demo-chat-promo {
  display: flex;
  align-items: center;
  justify-content: center;
  position: relative;
  left: auto;
  top: auto;
  transform: none;
  z-index: 40;
  grid-column: 2;
  justify-self: center;
  /* Always bound by the grid track — never overlap brand / header buttons. */
  width: 100%;
  max-width: 100%;
  max-height: none;
  min-width: 0;
  margin: 0;
  /* Inset so the pill shadow is not clipped by the grid cell edges. */
  padding: 2px 4px;
  box-sizing: border-box;
  font-family: ui-sans-serif, system-ui, -apple-system, "Segoe UI", Roboto, sans-serif;
  -webkit-user-select: none;
  user-select: none;
  pointer-events: none;
  overflow: visible;
}

.chat-container.assis-chat-v2.chat-maximized .assis-demo-chat-promo,
.chat-container.assis-chat-v2.chat-maximized .assis-demo-chat-promo.assis-demo-chat-promo--whatsapp {
  padding: 2px 5px;
}

.chat-container.assis-home-open .assis-demo-chat-promo {
  display: none !important;
}

/* Same swap as Banner settings preview — a touch slower than the demo 180ms. */
.assis-banner-swap-enter-active,
.assis-banner-swap-leave-active {
