.assis-order-pinned-picker {
  position: absolute;
  top: calc(100% + 6px);
  left: 0;
  right: auto;
  z-index: 30;
  display: flex;
  flex-direction: column;
  gap: 2px;
  min-width: 100%;
  max-width: min(280px, calc(100vw - 48px));
  max-height: min(220px, 40vh);
  overflow-x: hidden;
  overflow-y: auto;
  padding: 6px;
  box-sizing: border-box;
  border: 1px solid rgba(15, 23, 42, 0.08);
  border-radius: 14px;
  background: #ffffff;
  box-shadow: 0 10px 28px rgba(15, 23, 42, 0.12);
}

.assis-order-pinned-picker-item {
  appearance: none;
  display: flex;
  align-items: center;
  flex-wrap: wrap;
  gap: 6px;
  width: 100%;
  margin: 0;
  padding: 8px 10px;
  border: 0;
  border-radius: 10px;
