  font-weight: 500;
  color: #64748b;
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
}

.assis-order-popup {
  position: absolute;
  z-index: 40;
  bottom: calc(100% + 8px);
  inset-inline-start: 0;
  width: min(100%, 300px);
  max-width: min(100%, 300px);
}

.assis-order-popup-card {
  position: relative;
  display: flex;
  flex-direction: column;
  max-height: min(260px, 46vh);
  background: #fff;
  border: 1px solid rgba(15, 23, 42, 0.08);
  border-radius: 16px;
  box-shadow: 0 16px 40px rgba(15, 23, 42, 0.16);
  animation: assis-order-popup-in 160ms ease;
}

@media (max-width: 767px) {
  .assis-order-popup-card {
    max-height: min(460px, calc(100svh - 250px));
  }
}

.assis-order-popup-card::after {
  content: "";
  position: absolute;
  bottom: -6px;
  inset-inline-start: 28px;
  width: 12px;
  height: 12px;
  background: #fff;
  border-inline-end: 1px solid rgba(15, 23, 42, 0.08);
  border-bottom: 1px solid rgba(15, 23, 42, 0.08);
  transform: rotate(45deg);
}

.assis-order-popup-head {
  display: flex;
  align-items: center;
  gap: 8px;
  padding: 10px 12px 8px;
}

.assis-order-popup-change {
