}

.assis-order-popup-body {
  overflow: auto;
  min-height: 0;
  padding: 0 12px 12px;
}

.assis-order-popup .assis-order-card {
  width: 100%;
  padding: 0;
  border: none;
  border-radius: 0;
  box-shadow: none;
  background: transparent;
}

.assis-order-popup-pick {
  appearance: none;
  display: flex;
  flex-direction: row;
  align-items: center;
  gap: 10px;
  width: 100%;
  margin: 0 0 6px;
  padding: 8px 10px;
  border: 1px solid rgba(15, 23, 42, 0.08);
  border-radius: 12px;
  background: #fff;
  color: #0f172a;
  font: inherit;
  font-size: 13px;
  text-align: start;
  cursor: pointer;
}

.assis-order-popup-pick-media {
  flex: 0 0 auto;
  width: 44px;
  height: 44px;
  border-radius: 10px;
  overflow: hidden;
  background: #f7f8fa;
}

.assis-order-popup-pick-media--empty {
