}

.assis-order-popup-pick-media img {
  display: block;
  width: 100%;
  height: 100%;
  object-fit: cover;
}

.assis-order-popup-pick-copy {
  display: flex;
  flex-direction: column;
  align-items: flex-start;
  gap: 2px;
  min-width: 0;
}

.assis-order-popup-pick-copy span + span {
  color: #64748b;
  font-size: 12px;
}

@keyframes assis-order-popup-in {
  from {
    opacity: 0;
    transform: translateY(8px);
  }
  to {
    opacity: 1;
    transform: none;
  }
}

.assis-orders-dock-panel {
  position: relative;
  display: flex;
  flex-direction: column;
  gap: 8px;
  width: 100%;
  max-height: none;
  padding: 10px 12px 12px;
  box-sizing: border-box;
  border-radius: 16px;
  background: rgba(255, 255, 255, 0.96);
  border: 1px solid rgba(15, 23, 42, 0.06);
  box-shadow: 0 8px 24px rgba(15, 23, 42, 0.08);
  overflow: visible;
}

.assis-orders-dock .assis-orders-container {
  flex: none;
  min-height: auto;
  max-height: none;
  margin-bottom: 0;
  overflow: visible;
}

.assis-orders-dock .assis-order-selection-change {
  margin-inline-end: 0;
}

.assis-order-selection-change {
  appearance: none;
  border: none;
  background: transparent;
  padding: 0;
  color: #1d6fee;
  font-size: 11px;
  font-weight: 600;
  line-height: 1.3;
  cursor: pointer;
  font-family: inherit;
  text-align: start;
}

.assis-orders-dock .assis-orders-section-header,
.assis-orders-dock .assis-order-selection-subtitle,
.assis-orders-dock .assis-order-selection-list,
.assis-orders-dock .assis-order-card {
  width: 100%;
  max-width: 100%;
  box-sizing: border-box;
}

.chat-container.assis-chat-v2 .assis-orders-dock {
  padding: 0 2px;
}

.chat-container.assis-chat-v2 .assis-orders-dock-panel {
  background: #ffffff;
}

.assis-orders-section-header {
  display: flex;
  align-items: flex-start;
  justify-content: space-between;
  gap: 8px;
  width: min(300px, 100%);
  max-width: 100%;
  margin-bottom: 4px;
}

.assis-orders-container .assis-lh-section-title {
  margin: 0 0 2px;
  font-size: 11.5px;
  font-weight: 650;
  color: #64748b;
  letter-spacing: 0.02em;
}

.assis-order-selection-subtitle {
  margin: 0 0 2px;
  width: min(300px, 100%);
  max-width: 100%;
  font-size: 10.5px;
  line-height: 1.45;
  color: #9ca3af;
  font-weight: 500;
}

.assis-order-selection-list {
  display: flex;
  flex-direction: column;
  gap: 10px;
  width: min(300px, 100%);
  max-width: 100%;
  /* Show about 3 order rows, then scroll */
  max-height: calc((48px + 16px) * 3 + 10px * 2);
  overflow-x: hidden;
  overflow-y: auto;
  -webkit-overflow-scrolling: touch;
  overscroll-behavior: contain;
  padding: 2px 2px 4px;
  box-sizing: border-box;
  scrollbar-width: thin;
}

.assis-order-selection-list--popup {
  width: 100%;
  max-width: none;
}

.assis-order-selection-item {
  appearance: none;
  display: flex;
  flex-direction: row;
  align-items: center;
  gap: 10px;
  width: 100%;
  flex: 0 0 auto;
  margin: 0;
  padding: 8px 10px;
  border: var(--assis-chat-card-border, 1px solid rgba(15, 23, 42, 0.06));
  border-radius: var(--assis-chat-card-radius, 16px);
  background: var(--assis-chat-card-bg, #ffffff);
  box-shadow: var(--assis-chat-card-shadow, 0 4px 12px rgba(15, 23, 42, 0.06));
  cursor: pointer;
  font-family: inherit;
  text-align: inherit;
  box-sizing: border-box;
  animation: assis-product-card-in 0.4s cubic-bezier(0.22, 1, 0.36, 1) both;
  animation-delay: calc(0.06s + (var(--assis-order-i, 0) * 0.09s));
}

.assis-order-selection-item:hover {
  background: #fafbfc;
  border-color: rgba(29, 111, 238, 0.12);
}

.assis-order-selection-item-media {
  position: relative;
  flex: 0 0 auto;
  width: 48px;
  height: 48px;
  border-radius: 10px;
  background: #f7f8fa;
  overflow: hidden;
  display: flex;
  align-items: center;
  justify-content: center;
}

.assis-order-selection-item-media--empty {
  background: #f3f1ec;
}

.assis-order-selection-item-image {
  display: block;
  width: 100%;
  height: 100%;
  object-fit: cover;
}

.assis-order-selection-item-body {
  display: flex;
  flex: 1 1 auto;
  flex-direction: column;
  align-items: flex-start;
  gap: 3px;
  min-width: 0;
  text-align: left;
}

.assis-orders-container[dir="rtl"] .assis-order-selection-item-body {
  align-items: flex-end;
  text-align: right;
}

.assis-order-selection-item-heading {
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  gap: 5px;
  width: 100%;
}

.assis-order-selection-item-number {
  font-size: 12px;
  font-weight: 650;
  color: #1f2937;
}

.assis-order-selection-item-meta {
  width: 100%;
  font-size: 10.5px;
  font-weight: 500;
  line-height: 1.4;
  color: #9ca3af;
}

.assis-order-card {
  display: flex;
  flex-direction: column;
  gap: 6px;
  width: min(300px, 100%);
  max-width: 100%;
  padding: 8px 10px;
  box-sizing: border-box;
  border-radius: var(--assis-chat-card-radius, 14px);
  background: var(--assis-chat-card-bg, #ffffff);
  border: var(--assis-chat-card-border, 1px solid rgba(15, 23, 42, 0.06));
  box-shadow: var(--assis-chat-card-shadow, 0 3px 10px rgba(15, 23, 42, 0.05));
}

.assis-order-card-header {
  display: flex;
  align-items: flex-start;
  justify-content: space-between;
  gap: 8px;
}

.assis-order-card-heading {
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  gap: 6px;
  min-width: 0;
}

.assis-order-card-number {
  font-size: 12.5px;
  font-weight: 650;
  color: #1f2937;
}

.assis-order-card-status {
  display: inline-flex;
  align-items: center;
  height: 18px;
  padding: 0 7px;
  border-radius: 999px;
  background: #f9fafb;
  color: #374151;
  border: 1px solid #f3f4f6;
  font-size: 9.5px;
  font-weight: 550;
  line-height: 1;
}

.assis-order-card-status[data-color="indigo"] {
  background: #eef2ff;
  color: #4338ca;
  border-color: #e0e7ff;
}

.assis-order-card-status[data-color="amber"] {
  background: #fffbeb;
  color: #b45309;
  border-color: #fef3c7;
}

.assis-order-card-status[data-color="yellow"] {
  background: #fefce8;
  color: #a16207;
  border-color: #fef9c3;
}

.assis-order-card-status[data-color="blue"] {
  background: #eff6ff;
  color: #1d4ed8;
  border-color: #dbeafe;
}

.assis-order-card-status[data-color="red"] {
  background: #fef2f2;
  color: #b91c1c;
  border-color: #fee2e2;
}

.assis-order-card-status[data-color="green"] {
  background: #f0fdf4;
  color: #15803d;
  border-color: #dcfce7;
}

.assis-order-card-status[data-color="orange"] {
  background: #fff7ed;
  color: #c2410c;
  border-color: #ffedd5;
}

.assis-order-card-status[data-color="gray"] {
  background: #f9fafb;
  color: #374151;
  border-color: #f3f4f6;
}

.assis-order-card-date {
  flex: 0 0 auto;
  font-size: 10.5px;
  color: #9ca3af;
  font-weight: 500;
}

.assis-order-card-meta {
  font-size: 10.5px;
  color: #6b7280;
  line-height: 1.4;
}

.assis-order-card-meta-label {
  color: #9ca3af;
  font-weight: 500;
  margin-inline-end: 4px;
}

.assis-order-card-items {
  list-style: none;
  margin: 0;
  padding: 0;
  display: flex;
  flex-direction: column;
  gap: 8px;
}

.assis-order-card-item {
  display: flex;
  align-items: flex-start;
  gap: 8px;
  min-width: 0;
}

.assis-order-card-item--ask {
  cursor: pointer;
  border-radius: 10px;
  margin: 0 -4px;
  padding: 4px;
  transition: background-color 0.15s ease;
}

.assis-order-card-item--ask:hover,
.assis-order-card-item--ask:focus-visible {
  background: rgba(29, 111, 238, 0.06);
  outline: none;
}

.assis-order-card-item-media {
  flex: 0 0 auto;
  width: 40px;
  height: 40px;
  border-radius: 8px;
  overflow: hidden;
  background: #f7f8fa;
}

.assis-order-card-item-media--empty {
  background: #f3f1ec;
}

.assis-order-card-item-image {
  display: block;
  width: 100%;
  height: 100%;
  object-fit: cover;
}

.assis-order-card-item-main {
  flex: 1 1 auto;
  min-width: 0;
  display: flex;
  flex-direction: column;
  gap: 3px;
}

.assis-order-card-item-row {
  display: flex;
  align-items: flex-start;
  gap: 8px;
  min-width: 0;
}

.assis-order-card-item-body {
  flex: 1 1 auto;
  min-width: 0;
}

.assis-order-card-item-title {
  font-size: 11.5px;
  font-weight: 550;
  color: #1f2937;
  line-height: 1.3;
}

.assis-order-card-item-meta {
  margin-top: 2px;
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  gap: 4px;
  font-size: 10px;
  color: #9ca3af;
}

.assis-order-card-item-price-original {
  text-decoration: line-through;
  color: #9ca3af;
}

.assis-order-card-item-price {
  flex: 0 0 auto;
  white-space: nowrap;
  font-size: 11px;
  font-weight: 650;
  color: #1f2937;
}

.assis-order-card-item-discount {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 8px;
  font-size: 10px;
  line-height: 1.35;
  color: #6b7280;
}

.assis-order-card-item-discount-label {
  min-width: 0;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.assis-order-card-item-discount-value {
  flex: 0 0 auto;
}

.assis-order-card-discounts {
  display: flex;
  flex-direction: column;
  gap: 5px;
}

.assis-order-card-discount-chips {
  display: flex;
  flex-wrap: wrap;
  gap: 4px;
}

.assis-order-card-discount-chip {
  display: inline-flex;
  align-items: center;
  max-width: 100%;
  padding: 2px 7px;
  border-radius: 999px;
  background: rgba(29, 111, 238, 0.08);
  color: #1d6fee;
  font-size: 9.5px;
  font-weight: 600;
  line-height: 1.3;
  word-break: break-word;
}

.assis-order-card-totals,
.assis-order-card-fulfillment {
  display: flex;
  flex-direction: column;
  gap: 3px;
  padding-top: 5px;
  border-top: 1px solid rgba(15, 23, 42, 0.06);
}

.assis-order-card-fulfillment-title {
  margin: 0 0 2px;
  font-size: 10px;
  font-weight: 700;
  color: #475569;
}

.assis-order-card-total-row,
.assis-order-card-fulfillment-row {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 8px;
  font-size: 10px;
  line-height: 1.35;
  color: #6b7280;
}

.assis-order-card-total-row--nested {
  padding-inline-start: 8px;
  color: #9ca3af;
}

.assis-order-card-total-row--strong {
  font-size: 11px;
  font-weight: 700;
  color: #1f2937;
}

.assis-order-card-fulfillment-label,
.assis-order-card-fulfillment-value {
  font-size: 10px;
  line-height: 1.35;
  color: #6b7280;
}

.assis-order-card-fulfillment-link {
  color: #1d6fee;
  text-decoration: none;
  font-size: 10px;
  font-weight: 600;
  word-break: break-all;
}

.assis-order-card-fulfillment-link:hover {
  text-decoration: underline;
}

.assis-order-card-total {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 8px;
  padding-top: 6px;
  border-top: 1px solid rgba(15, 23, 42, 0.06);
  font-size: 11.5px;
  color: #6b7280;
}

.assis-order-card-total strong {
  color: #111827;
  font-weight: 650;
}

.chat-container.assis-chat-v2 .message.sender-ai .message-content-container,
.chat-container.assis-chat-v2 .message.sender-agent .message-content-container,
.chat-container.assis-chat-v2 .message.sender-assis .message-content-container,
.chat-container.assis-chat-v2 .message.sender-business .message-content-container {
  display: flex;
  flex-direction: row;
  align-items: flex-start;
  gap: 8px;
  max-width: 100%;
  width: auto;
  min-width: 0;
}

.chat-container.assis-chat-v2 .assis-msg-heart {
  width: 15px;
  height: 15px;
  display: block;
  flex-shrink: 0;
  margin-top: 2px;
}

.chat-container.assis-chat-v2 .loading-message-bubble {
  align-items: flex-start;
  gap: 8px;
}

.chat-container.assis-chat-v2 .loading-message-bubble .message-bubble {
  background: transparent;
  border: none;
  box-shadow: none;
  border-radius: 0;
  padding: 2px 0;
  margin: 0;
  min-height: 16px;
  max-width: 100%;
  display: flex;
  align-items: baseline;
}

.assis-gemini-caret {
  display: inline-block;
  width: 1.5px;
  height: 0.85em;
  margin-inline-start: 1px;
  background: #1d6fee;
  vertical-align: -1px;
  animation: assis-gemini-caret 0.7s step-end infinite;
}

.assis-thinking-line[dir="rtl"] .assis-gemini-caret,
.assis-typewriter[dir="rtl"] .assis-gemini-caret {
  margin-inline-start: 0;
  margin-inline-end: 1px;
}

.assis-thinking-line {
  margin: 0;
  font-size: 12px;
  line-height: 1.55;
  white-space: pre-wrap;
}

.assis-thinking-line[dir="rtl"],
.assis-typewriter[dir="rtl"],
.assis-typewriter[dir="rtl"] p {
  text-align: right;
  direction: rtl;
  unicode-bidi: isolate;
}

.assis-thinking-line[dir="ltr"],
.assis-typewriter[dir="ltr"],
.assis-typewriter[dir="ltr"] p {
  text-align: left;
  direction: ltr;
}

.assis-thinking-text {
  color: #9ca3af;
  font-weight: 400;
}

.assis-typewriter {
  word-break: normal;
  overflow-wrap: anywhere;
  white-space: pre-wrap;
}

.assis-typewriter p {
  white-space: pre-wrap;
}

@keyframes assis-gemini-caret {
  50% { opacity: 0; }
}

.chat-container.assis-chat-v2 .ai-agent-info {
  display: flex;
  align-items: flex-start;
  align-self: flex-start;
  margin: 0;
  padding: 0;
  background: transparent;
  box-shadow: none;
  gap: 0;
  width: 15px;
  height: 15px;
}

.chat-container.assis-chat-v2 .message.sender-ai .message-bubble,
.chat-container.assis-chat-v2 .message.sender-agent .message-bubble,
.chat-container.assis-chat-v2 .message.sender-assis .message-bubble,
.chat-container.assis-chat-v2 .message.sender-business .message-bubble {
  background: transparent;
  border: none;
  color: #1a1a1a;
  border-radius: 0;
  box-shadow: none;
  /* Space before the start of the copy (RTL = right, LTR = left). */
  padding: 2px 0;
  padding-inline-start: 8px;
  max-width: 100%;
  width: fit-content;
  min-width: 0;
  font-size: 13px !important;
  line-height: 1.55;
  word-break: normal;
  overflow-wrap: anywhere;
}

.chat-container.assis-chat-v2 .message.sender-ai .message-bubble :deep(p),
.chat-container.assis-chat-v2 .message.sender-agent .message-bubble :deep(p),
.chat-container.assis-chat-v2 .message.sender-assis .message-bubble :deep(p) {
  margin: 0 0 1em;
}

.chat-container.assis-chat-v2 .message.sender-ai .message-bubble :deep(p:last-child),
.chat-container.assis-chat-v2 .message.sender-agent .message-bubble :deep(p:last-child),
.chat-container.assis-chat-v2 .message.sender-assis .message-bubble :deep(p:last-child) {
  margin-bottom: 0;
}

.chat-container.assis-chat-v2 .ai-human-contact-sheet {
  display: flex;
}

.chat-container.assis-chat-v2:has(.chat-input-area > .ai-human-contact-sheet--v2:not(.ai-human-contact-sheet--collapsed)) .assis-suggest-chips {
  display: none;
}

.chat-container.assis-chat-v2 .chat-input-area {
  position: relative;
  display: flex;
  flex-direction: column;
  align-items: stretch;
  border-top: none;
  background: transparent;
  padding: 18px 14px 0;
  box-shadow: none;
}

.chat-container.assis-chat-v2 .flex.gap-2 {
  position: relative;
  display: flex;
  align-items: center;
  width: 100%;
  max-width: 100%;
  gap: 8px;
  margin: 0;
  padding: 0;
}

.chat-container.assis-chat-v2 .input-container {
  position: relative;
  flex: 1 1 auto;
  min-width: 0;
  min-height: 48px;
  height: auto;
  align-items: center;
  background: #ffffff;
  border-radius: 999px;
  border: 1px solid rgba(148, 163, 184, 0.42);
  box-shadow: 0 1px 2px rgba(15, 23, 42, 0.04);
  padding: 10px 14px !important;
  gap: 10px;
}

.chat-container.assis-chat-v2 .input-container:focus-within {
  border-color: #1d6fee;
  box-shadow: 0 0 0 3px rgba(29, 111, 238, 0.14);
}

.chat-container.assis-chat-v2 .chat-input {
  font-size: 13px !important;
  line-height: 20px;
  padding: 0;
  height: 20px;
  min-height: 20px;
  max-height: 80px;
  overflow-x: hidden;
  overflow-y: auto;
}

.chat-container.assis-chat-v2 .chat-input::placeholder {
  font-size: 13px !important;
  color: rgba(100, 116, 139, 0.85);
}

.chat-container.assis-chat-v2 .attach-btn,
.chat-container.assis-chat-v2 .emoji-btn {
  width: 20px;
  height: 20px !important;
  opacity: 0.62;
  color: #64748b;
  flex-shrink: 0;
}

.chat-container.assis-chat-v2 .attach-btn:hover,
.chat-container.assis-chat-v2 .emoji-btn:hover:not(:disabled) {
  opacity: 1;
  color: #475569;
}

.chat-container.assis-chat-v2 .send-btn {
  position: static;
  right: auto;
  left: auto;
  top: auto;
  bottom: auto;
  translate: none;
  transform: none;
  z-index: 2;
  width: 40px;
  min-width: 40px;
  height: 40px;
  border-radius: 50%;
  background: #1d6fee;
  box-shadow: 0 2px 8px rgba(29, 111, 238, 0.32);
  flex: 0 0 auto;
  align-self: center;
}

.chat-container.assis-chat-v2 .send-btn:hover:not(:disabled) {
  background: #1557c0;
}

.chat-container.assis-chat-v2 .send-btn:disabled {
  opacity: 0.45;
  box-shadow: none;
}

.chat-container.assis-chat-v2 .chat-input-multiline .input-container {
  border-radius: 22px;
  align-items: flex-end;
}

.chat-container.assis-chat-v2 .chat-input-multiline .send-btn {
  align-self: flex-end;
  margin-bottom: 4px;
}

.chat-container.assis-chat-v2 .flex-rtl .send-btn {
  right: auto;
  left: auto;
}

.chat-container.assis-chat-v2 .flex-rtl .input-container {
  padding: 10px 14px !important;
}

.assis-suggest-chips {
  display: flex;
  flex-wrap: nowrap;
  align-items: center;
  gap: 8px;
  width: 100%;
  margin: 0 0 10px;
  padding: 8px 18px 4px 0;
  overflow-x: auto;
  scrollbar-width: none;
  mask-image: linear-gradient(to right, #000 0, #000 calc(100% - 22px), transparent 100%);
}

.assis-suggest-chips--rtl {
  justify-content: flex-start;
  direction: rtl;
  padding: 8px 0 4px 18px;
  mask-image: linear-gradient(to left, #000 0, #000 calc(100% - 22px), transparent 100%);
}

.assis-suggest-chips::-webkit-scrollbar {
  display: none;
}

.assis-suggest-chips button {
  flex: 0 0 auto;
  appearance: none;
  display: inline-flex;
  align-items: center;
  gap: 8px;
  height: auto;
  padding-block: 4px;
  padding-inline: 4px 14px;
  border: 1px solid rgba(29, 111, 238, 0.18);
  border-radius: 9999px;
  background: rgba(255, 255, 255, 0.96);
  color: #374151;
  font-size: 13px;
  font-weight: 500;
  letter-spacing: -0.01em;
  font-family: inherit;
  line-height: 1.3;
  white-space: nowrap;
  box-shadow: 0 8px 18px rgba(15, 23, 42, 0.06);
  animation: assis-agent-card-in 0.42s cubic-bezier(0.22, 1, 0.36, 1) both;
  cursor: pointer;
}

.assis-suggest-chips button:nth-child(1),
.assis-home-chips button:nth-child(1) { animation-delay: 0.02s; }
.assis-suggest-chips button:nth-child(2),
.assis-home-chips button:nth-child(2) { animation-delay: 0.08s; }
.assis-suggest-chips button:nth-child(3),
.assis-home-chips button:nth-child(3) { animation-delay: 0.14s; }
.assis-suggest-chips button:nth-child(4),
.assis-home-chips button:nth-child(4) { animation-delay: 0.2s; }
.assis-suggest-chips button:nth-child(5),
.assis-home-chips button:nth-child(5) { animation-delay: 0.26s; }
.assis-suggest-chips button:nth-child(6),
.assis-home-chips button:nth-child(6) { animation-delay: 0.32s; }

.assis-suggest-chips button:hover {
  color: #1d6fee;
  background: #ffffff;
  border-color: rgba(29, 111, 238, 0.28);
  box-shadow: 0 8px 18px rgba(15, 23, 42, 0.08);
}

.chat-container::after {
  content: "";
  position: absolute;
  inset: 0;
  background: rgba(15, 23, 42, 0.08);
  z-index: 3;
  opacity: 0;
  pointer-events: none;
  transition: opacity 0.45s ease;
}
.chat-container.assis-cart-focus::after {
  opacity: 1;
}
.chat-container.assis-cart-focus .message.assis-cart-action,
.chat-container.assis-cart-focus .assis-message-question,
.chat-container.assis-cart-focus .assis-products-container,
.chat-container.assis-cart-focus .assis-checkout-card,
.chat-container.assis-cart-focus .assis-checkout-inline,
.chat-container.assis-cart-focus .cart-upsell-chat-lead,
.chat-container.assis-cart-focus .cart-upsell {
  position: relative;
  z-index: 4;
}
.chat-container.assis-cart-focus .assis-checkout-card,
.chat-container.assis-cart-focus .assis-products-container,
.chat-container.assis-cart-focus .cart-upsell {
  filter: drop-shadow(0 16px 28px rgba(15, 23, 42, 0.22));
}
.chat-container.assis-chat-v2 .assis-message-question,
.chat-container.assis-chat-v2.assis-chat-he-flip .assis-message-question {
  display: flex;
  flex-direction: row;
  align-items: flex-start;
  justify-content: flex-start;
  width: 100%;
  max-width: 100%;
