  text-align: left;
  margin-left: 0;
  margin-right: auto;
}
.assis-message-question .assis-follow-replies,
.assis-message-question + .assis-follow-replies {
  margin-top: 0;
}
.assis-follow-replies {
  display: flex;
  flex-direction: row;
  flex-wrap: wrap;
  align-items: center;
  justify-content: flex-start;
  gap: 6px;
