  margin-right: auto;
}

.assis-follow-replies--he {
  direction: rtl;
  align-self: flex-end;
  margin-left: auto;
  margin-right: 0;
  justify-content: flex-end;
}

.chat-container.assis-chat-v2 .assis-follow-replies--he,
.chat-container.assis-chat-v2 .assis-message-question .assis-follow-replies--he {
  margin-left: auto;
  margin-right: 0;
  justify-content: flex-end;
}
.chat-container.assis-chat-v2 .assis-message-question[dir="ltr"] .assis-message-question-main {
  align-items: flex-start;
  margin-left: 0;
  margin-right: auto;
}

.assis-follow-reply {
  appearance: none;
  display: inline-flex;
  align-items: center;
  flex: 0 0 auto;
  max-width: 100%;
  margin: 0;
  padding: 7px 13px;
  border: 1px solid rgba(29, 111, 238, 0.16);
  border-radius: 999px;
  background: rgba(255, 255, 255, 0.96);
  color: #374151;
  box-shadow: 0 4px 14px rgba(15, 23, 42, 0.05);
  font-family: inherit;
  font-size: 13px;
  font-weight: 500;
  letter-spacing: -0.01em;
  line-height: 1.2;
  text-align: start;
  white-space: nowrap;
  cursor: pointer;
  animation: assis-agent-card-in 0.5s cubic-bezier(0.22, 0.61, 0.36, 1) both;
  animation-delay: calc(0.1s + (var(--reply-i, 0) * 0.12s));
  transition: transform 0.15s ease, box-shadow 0.15s ease, border-color 0.15s ease, background 0.15s ease, color 0.15s ease;
}

.assis-follow-reply:hover:not(:disabled) {
  color: #1d6fee;
  background: #ffffff;
  border-color: rgba(29, 111, 238, 0.34);
  transform: translateY(-1px);
  box-shadow: 0 8px 18px rgba(29, 111, 238, 0.12);
}

.assis-follow-reply:disabled {
  cursor: default;
}

.assis-follow-reply:disabled:not(.is-selected) {
  background: rgba(255, 255, 255, 0.7);
  border-color: rgba(15, 23, 42, 0.06);
  color: #9aa3af;
  box-shadow: none;
}

.assis-follow-reply.is-selected {
  background: #e8f3ff;
  border-color: rgba(29, 111, 238, 0.4);
  color: #1d6fee;
  box-shadow: none;
  font-weight: 600;
}

.assis-chat-footer {
  display: grid !important;
  grid-template-columns: minmax(0, 1fr) auto minmax(0, 1fr);
  align-items: center;
  width: 100%;
  padding: 8px 14px 10px;
  background: transparent;
  text-align: unset;
  box-sizing: border-box;
}

.chat-container.assis-chat-v2 .chat-footer {
  border-top: none;
  background: transparent;
  padding-left: 14px;
  padding-right: 14px;
}

.assis-home {
  position: relative;
  flex: 1;
  min-height: 0;
  display: flex;
  flex-direction: column;
  padding: 8px 24px 16px;
  box-sizing: border-box;
  font-family: ui-sans-serif, system-ui, -apple-system, "Segoe UI", Roboto, sans-serif;
  color: #1a1a1a;
  overflow: visible;
}

.assis-home-main {
  position: relative;
  display: flex;
  flex-direction: row;
  align-items: center;
  justify-content: space-between;
  gap: 12px;
  flex: 1;
  min-height: 0;
  overflow: visible;
  padding: 8px;
}

.assis-home-copy {
  display: flex;
  flex-direction: column;
  align-items: flex-start;
  text-align: start;
  max-width: 220px;
  width: 100%;
  flex: 1 1 160px;
}

.assis-home-brand {
  display: grid;
  place-items: start;
  margin: 0 0 14px;
}

.assis-home-brand-icon {
  width: 34px;
  height: 34px;
  display: block;
  overflow: visible;
  filter: drop-shadow(0 1px 2px rgba(29, 111, 238, 0.28));
}

.assis-home-title {
  margin: 0 0 8px;
  font-size: 20px;
  font-weight: 700;
  letter-spacing: -0.02em;
  line-height: 1.15;
  color: #303030;
}

.assis-home-body {
  margin: 0;
  max-width: 210px;
  font-size: 13px;
  line-height: 1.4;
  color: #5b5b5b;
  font-weight: 400;
}

.assis-home-cards {
  position: relative;
  flex: 0 0 168px;
  width: 168px;
  height: 156px;
  pointer-events: none;
  overflow: visible;
}

.assis-home-cards::before {
  content: "";
  position: absolute;
  left: 48%;
  top: 48%;
  width: 180px;
  height: 150px;
  translate: -50% -50%;
  border-radius: 50%;
  background: radial-gradient(
    ellipse at center,
    rgba(29, 111, 238, 0.38) 0%,
    rgba(29, 111, 238, 0.16) 42%,
    rgba(29, 111, 238, 0.05) 65%,
    transparent 78%
  );
  filter: blur(16px);
  pointer-events: none;
  z-index: 0;
}

.assis-home-card {
  position: absolute;
  width: 112px;
  display: flex;
  flex-direction: column;
  overflow: hidden;
  border-radius: 16px;
  background: #ffffff;
  border: none;
  padding: 0;
  box-shadow: 0 0 0 3px #ffffff, 0 0 0 4px rgba(15, 23, 42, 0.05), 0 14px 30px rgba(15, 23, 42, 0.16);
  box-sizing: border-box;
  color: #3a3f46;
  pointer-events: auto;
  transform-origin: center center;
  isolation: isolate;
  z-index: 1;
  /* Quiet fan drift — no pop / lift on auto-rotate. */
  transition:
    rotate 0.72s cubic-bezier(0.33, 1, 0.68, 1),
    translate 0.72s cubic-bezier(0.33, 1, 0.68, 1),
    scale 0.72s cubic-bezier(0.33, 1, 0.68, 1),
    box-shadow 0.45s ease,
    top 0.72s cubic-bezier(0.33, 1, 0.68, 1),
    left 0.72s cubic-bezier(0.33, 1, 0.68, 1),
    opacity 0.55s ease;
}

.assis-home-card-link {
  display: flex;
  flex-direction: column;
  color: inherit;
  text-decoration: none;
  min-width: 0;
  -webkit-tap-highlight-color: transparent;
  tap-highlight-color: transparent;
  -webkit-touch-callout: none;
  outline: none;
}

@keyframes assis-home-card-in {
  from {
    opacity: 0;
    translate: 0 6px;
    scale: 0.98;
  }
  to {
    opacity: 1;
    translate: 0 0;
    scale: 1;
  }
}

/* New back card: quiet fade-in under the leaving front. */
.assis-home-card-fan-enter-active {
  z-index: 0 !important;
  animation: assis-home-card-in 0.7s cubic-bezier(0.33, 1, 0.68, 1) 0.06s both;
}

.assis-home-card-fan-appear-active {
  animation: assis-home-card-in 0.55s cubic-bezier(0.33, 1, 0.68, 1) both;
}

.assis-home-card-fan-appear-active:nth-child(1) { animation-delay: 0.06s; }
.assis-home-card-fan-appear-active:nth-child(2) { animation-delay: 0.14s; }
.assis-home-card-fan-appear-active:nth-child(3) { animation-delay: 0.22s; }

/* Leaving front fades out gently — no pop, blur, or hard lift. */
.assis-home-card-fan-leave-active {
  position: absolute !important;
  transition:
    opacity 0.65s cubic-bezier(0.33, 1, 0.68, 1),
    transform 0.65s cubic-bezier(0.33, 1, 0.68, 1);
  pointer-events: none !important;
  z-index: 4 !important;
}

.assis-home-card-fan-leave-to {
  opacity: 0;
  transform: scale(0.97) translateY(-4px);
}

.assis-home-card-fan-move {
  transition: transform 0.72s cubic-bezier(0.33, 1, 0.68, 1);
}

@media (prefers-reduced-motion: reduce) {
  .assis-home-card-fan-enter-active,
  .assis-home-card-fan-appear-active,
  .assis-home-card-fan-leave-active,
  .assis-home-card-fan-move {
    animation: none;
    transition: opacity 0.2s ease;
  }
}

/* Compact web: exact FURI 2-card stack — front left (-8deg), back lower-right (+10deg) */
.assis-home-card--a {
  top: 0;
  left: 0;
  rotate: -8deg;
  z-index: 3;
}

.assis-home-card--b {
  top: 36px;
  left: 52px;
  rotate: 10deg;
  z-index: 2;
}

.assis-home-card--c {
  /* Parked at maximized coords while hidden — no slide/fade on minimize */
  display: flex;
  top: 56px;
  left: 168px;
  rotate: 9deg;
  z-index: 1;
  opacity: 0;
  visibility: hidden;
  pointer-events: none;
  transition: none;
}

.chat-container.chat-maximized .assis-home-card--c {
  opacity: 1;
  visibility: visible;
  pointer-events: auto;
}

.assis-home-card:hover {
  rotate: 0deg;
  translate: 0 -6px;
  scale: 1.05;
  z-index: 5;
  box-shadow: 0 0 0 3px #ffffff, 0 0 0 4px rgba(29, 111, 238, 0.16), 0 22px 44px rgba(15, 23, 42, 0.2);
