  .heart-text-bubble {
    padding: 8px 16px 8px 32px;
  }

  .heart-image {
    rotate: -10deg;
    /* left: -40px;
    bottom: -12px; */
  }

  .no-rotation {
    rotate: 0deg;
  }
}

.button-left .heart-text-bubble {
  margin-right: 0;
  margin-left: -5px;
  left: 72px;
  top: 12px;
}

.button-left .heart-text-bubble.bubble-whatsapp {
  left: 85px;
}

.button-left .heart-text-bubble::after {
  right: auto;
  left: -8px;
  border-left: none;
  border-right: 8px solid #ffffff;
}

.button-right {
  /* right: 50px;
  left: auto; */
  /* justify-content: flex-end; */

  .heart-text-bubble {
    padding: 8px 32px 8px 16px;
    right: 72px;
    top: 12px;
  }

  .heart-image {
    rotate: 10deg;
    /* right: -40px;
    bottom: -12px; */
  }

  .no-rotation {
    rotate: 0deg;
  }
}

.button-right .heart-text-bubble.bubble-whatsapp {
  right: 85px;
}

/* Size scaling variants */
.button-small {
  transform: scale(0.8);
  bottom: 20px;

  &.plan-powered-by-assis {
    transform: scale(0.52);
  }

  &.plan-powered-by-assis:active {
    transform: scale(0.48);
  }

  /* Mobile */
  @media (max-width: 480px) {
    bottom: 8px;
  }

  &.button-right {
    right: 20px;

    /* Mobile */
    @media (max-width: 480px) {
      right: 8px;
    }
  }

  &.button-left {
    left: 20px;

    /* Mobile */
    @media (max-width: 480px) {
      left: 8px;
    }
  }
}

.button-medium {
  transform: scale(1);
  bottom: 24px;

  &.plan-powered-by-assis {
    transform: scale(0.60);
  }

  /* Mobile */
  @media (max-width: 480px) {
    bottom: 8px;
  }

  &.button-right {
    right: 24px;

    /* Mobile */
    @media (max-width: 480px) {
      right: 8px;
    }
  }

  &.button-left {
    left: 24px;

    /* Mobile */
    @media (max-width: 480px) {
      left: 8px;
    }
  }
}

.button-large {
  transform: scale(1.2);
  bottom: 24px;

  &.plan-powered-by-assis {
    transform: scale(0.68);
  }

  /* Mobile */
  @media (max-width: 480px) {
    bottom: 8px;
  }

  &.button-right {
    right: 24px;

    /* Mobile */
    @media (max-width: 480px) {
      right: 8px;
    }
  }

  &.button-left {
    left: 24px;

    /* Mobile */
    @media (max-width: 480px) {
      left: 8px;
    }
  }
}

@media (max-width: 767px) {
  .fixed-heart-btn.plan-powered-by-assis,
  .fixed-heart-btn.plan-powered-by-assis.button-small,
  .fixed-heart-btn.plan-powered-by-assis.button-medium,
  .fixed-heart-btn.plan-powered-by-assis.button-large {
    width: 52px;
    height: 52px;
    min-width: 52px;
    max-width: 52px;
    transform: none;
    border-radius: 16px;
    bottom: max(16px, env(safe-area-inset-bottom));
    overflow: visible;
    box-sizing: border-box;
  }

  .fixed-heart-btn.plan-powered-by-assis.button-right {
    right: max(16px, env(safe-area-inset-right));
    left: auto;
  }

  .fixed-heart-btn.plan-powered-by-assis.button-left {
    left: max(16px, env(safe-area-inset-left));
    right: auto;
  }

  .fixed-heart-btn.plan-powered-by-assis:active {
    transform: scale(0.94);
  }
}

/* Bubble size variants */
.heart-bubble-small {
  padding: 6px 10px 6px 6px;
  font-size: 12px;
}

/* Heart Text Bubble */
.heart-text-bubble {
  display: flex;
  align-items: center;
  gap: 8px;
  background-color: #ffffffea;
  border: 1px solid #007bff;
  border-radius: 20px;
  box-shadow: 0 2px 8px rgba(0, 0, 0, 0.1);
  margin-right: -5px;
  position: relative;
  z-index: 2;

}

.ai-single-quick-bubble {
  cursor: pointer;
  position: relative;
}

.ai-single-quick-bubble:hover,
.ai-single-quick-bubble:active {
  border: 1px solid rgba(200, 222, 255, 0.65);
  box-shadow: rgba(0, 0, 0, 0.10) 0px 4px 16px, rgba(0, 0, 0, 0.06) 0px 1px 4px;
  transform: translateY(0px);
}

.ai-single-quick-bubble-wrap {
  position: relative;
  display: inline-flex;
  align-items: center;
}

.ai-single-quick-bubble-close {
  position: absolute;
  top: -5px;
  right: -5px;
  width: 18px;
  height: 18px;
  border-radius: 9999px;
  border: 1px solid rgba(229, 231, 235, 0.9);
  background: rgba(255, 255, 255, 0.95);
  display: inline-flex;
  align-items: center;
  justify-content: center;
  padding: 0;
  cursor: pointer;
  box-shadow: 0 1px 4px rgba(0, 0, 0, 0.08);
}

.ai-single-quick-bubble-close-left {
  top: -5px;
  left: -5px;
}

.ai-single-quick-bubble-close:hover {
  background: rgba(255, 255, 255, 1);
  border-color: rgba(209, 213, 219, 1);
}

.ai-single-quick-bubble-close:active {
  transform: translateY(0.5px);
}


.bubble-text {
  font-size: 14px;
  font-weight: 400;
  color: #026ee7;
  white-space: nowrap;
  text-align: right;
}

/* Bubble label appear animation (AI only) */
.bubble-label-enter-active {
  animation: bubble-label-in 800ms cubic-bezier(0.16, 1, 0.3, 1) both;
  will-change: opacity, transform, filter;
}
.bubble-label-leave-active {
  animation: bubble-label-in 260ms cubic-bezier(0.4, 0, 0.2, 1) reverse both;
  will-change: opacity, transform, filter;
}
@keyframes bubble-label-in {
  from {
    opacity: 0;
    transform: translateY(10px) scale(0.985);
    filter: blur(3px);
  }
  to {
    opacity: 1;
    transform: translateY(0) scale(1);
    filter: blur(0);
  }
}

.whatsapp-number {
  display: inline-flex;
  align-items: center;
  margin-left: 0px;
  margin-right: 4px;
}

.whatsapp-number svg {
  width: 18px;
  height: 18px;
  fill: #2563eb;
}

.whatsapp-number--ai {
  display: inline-flex;
  align-items: center;
  fill: #60a5fa;
}

/* RTL support for bubble text */
.bubble-text[dir="rtl"] {
  text-align: right;
  direction: rtl;
}

.bubble-text[dir="ltr"] {
  text-align: left;
  direction: ltr;
}

/* Heart Image */
.heart-image {
  position: absolute;
  width: 100%;
  height: 100%;

  z-index: 3;
  transition: transform 0.3s ease;
  animation: heartbeat 1.5s ease-in-out infinite;
  --hover-scale: 1;
  filter: drop-shadow(rgba(59, 130, 246, 0.5) 0px 3px 8px) drop-shadow(rgba(0, 0, 0, 0.06) 0px 1px 3px);
  -webkit-tap-highlight-color: transparent;
  pointer-events: none;
}

.heart-image.no-heartbeat {
  animation: none;
}

.heart-unread {
  position: absolute;
  z-index: 6;
  top: -2px;
  left: -3px;
  display: grid;
  place-items: center;
  min-width: 16px;
  height: 16px;
  padding: 0 4px;
  border-radius: 999px;
  background: #1d6fee;
  color: #fff;
  font-size: 10px;
  font-weight: 700;
  line-height: 1;
  font-family: ui-sans-serif, system-ui, sans-serif;
  box-shadow: 0 0 0 2px #fff;
  pointer-events: none;
  animation:
    heart-unread-enter 0.55s cubic-bezier(0.22, 1, 0.36, 1) both,
    heart-unread-pulse 1.7s ease-in-out 0.55s infinite;
}

.heart-unread::before {
  content: '';
  position: absolute;
  inset: 0;
  border-radius: inherit;
  background: #1d6fee;
  z-index: -1;
  pointer-events: none;
  animation: heart-unread-echo 1.7s ease-out 0.55s infinite;
}

.button-right .heart-unread,
.button-left .heart-unread {
  left: -3px;
  right: auto;
}

.button-right .heart-unread--on-hint,
.button-left .heart-unread--on-hint {
  top: -4px;
  left: -4px;
  right: auto;
  min-width: 18px;
  height: 18px;
  font-size: 11px;
}

@keyframes heart-unread-enter {
  0% { opacity: 0; transform: scale(0.2); }
  55% { opacity: 1; transform: scale(1.28); }
  100% { opacity: 1; transform: scale(1); }
}

@keyframes heart-unread-pulse {
  0%, 100% { transform: scale(1); }
  50% { transform: scale(1.08); }
}

@keyframes heart-unread-echo {
  0% { transform: scale(1); opacity: 0.5; }
  100% { transform: scale(2.35); opacity: 0; }
}

.heart-typing-dots {
  position: absolute;
  z-index: 6;
  top: auto;
  bottom: -14px;
  left: 50%;
  display: inline-flex;
  align-items: center;
  gap: 4px;
  transform: translateX(-50%);
  pointer-events: none;
}

.heart-typing-dots i {
  width: 5px;
  height: 5px;
  border-radius: 50%;
  background: #1d6fee;
  opacity: 0.85;
}

.heart-typing-dots--active i {
  opacity: 0.35;
  animation: heart-typing-wave 1.05s ease-in-out infinite;
}

.heart-typing-dots--active i:nth-child(2) { animation-delay: 0.15s; }
.heart-typing-dots--active i:nth-child(3) { animation-delay: 0.3s; }

/* Idle (not waiting on AI): occasional soft bounce so the dots stay alive. */
.heart-typing-dots--idle i {
  animation: heart-typing-idle 5.8s ease-in-out infinite;
}

.heart-typing-dots--idle i:nth-child(2) { animation-delay: 0.12s; }
.heart-typing-dots--idle i:nth-child(3) { animation-delay: 0.24s; }

.heart-unread__count {
  position: relative;
  z-index: 1;
}

@keyframes heart-typing-wave {
  0%, 100% { opacity: 0.35; transform: translate3d(0, 0, 0) scale(0.85); }
  50% { opacity: 1; transform: translate3d(0, -4px, 0) scale(1); }
}

@keyframes heart-typing-idle {
  0%, 10%, 100% { opacity: 0.75; transform: translate3d(0, 0, 0) scale(0.92); }
  3% { opacity: 1; transform: translate3d(0, -3.5px, 0) scale(1.08); }
  6% { opacity: 0.85; transform: translate3d(0, 0, 0) scale(1); }
  14%, 100% { opacity: 0.75; transform: translate3d(0, 0, 0) scale(0.92); }
}

@media (prefers-reduced-motion: reduce) {
  .heart-unread,
  .heart-unread::before {
    animation: none;
  }
  .heart-typing-dots--active i,
  .heart-typing-dots--idle i {
    animation: none;
    opacity: 0.85;
  }
}

.heart-image:hover {
  animation-play-state: paused;
}

.fixed-heart-btn:active {
  transform: scale(0.95);
}

/* Guest Input Section */
.guest-input-section {
  text-align: center;
  margin-bottom: 0;
  display: flex;
  flex-direction: column;
  flex: 1;
  min-height: 0;
  height: 100%;
}

.guest-input-title {
  font-size: 24px;
  font-weight: 700;
  color: #3b82f6;
  margin-bottom: 8px;
}

.guest-input-description {
  font-size: 16px;
  color: #6b7280;
  margin-bottom: 20px;
  line-height: 1.5;
}

.step-content {
  flex: 1;
  margin-bottom: 20px;
  /* Space between content and navigation */
  min-height: 0;
  overflow-y: auto;
  display: flex;
  flex-direction: column;
  justify-content: center;
}

.input-group {
  display: flex;
  gap: 12px;
  margin-bottom: 20px;
  align-items: center;
}

.guest-name-input {
  flex: 1;
  padding: 14px 16px;
  border: 2px solid #e5e7eb;
  border-radius: 10px;
  font-size: 16px;
  outline: none;
  transition: all 0.2s ease;
}

/* RTL support for guest name input */
.guest-name-input[dir="rtl"] {
  text-align: right;
  direction: rtl;
}

.guest-name-input[dir="ltr"] {
  text-align: left;
  direction: ltr;
}

.guest-name-input:focus {
  border-color: #3b82f6;
  box-shadow: 0 0 0 3px rgba(59, 130, 246, 0.1);
}

.next-btn {
  padding: 14px 24px;
  background: #3b82f6;
  color: white;
  border: none;
  border-radius: 10px;
  cursor: pointer;
  font-size: 16px;
  font-weight: 600;
  transition: all 0.2s ease;
  white-space: nowrap;
}

.next-btn:hover:not(:disabled) {
  background: #2563eb;
  transform: translateY(-1px);
}

.next-btn:disabled {
  background: #d1d5db;
  cursor: not-allowed;
  color: #9ca3af;
  transform: none;
}

.back-btn {
  padding: 10px 20px;
  background: #f3f4f6;
  color: #3b82f6;
  border: 1px solid #e5e7eb;
  border-radius: 8px;
  cursor: pointer;
  font-size: 14px;
  font-weight: 500;
  transition: all 0.2s ease;
}

.back-btn:hover {
  background: #e5e7eb;
  border-color: #d1d5db;
}

/* Contact Inputs */
.contact-inputs {
  display: flex;
  flex-direction: column;
  gap: 16px;
  margin-bottom: 20px;
}

.input-field {
  display: flex;
  flex-direction: column;
  align-items: flex-start;
}

.input-field label {
  font-size: 14px;
  color: #6b7280;
  margin-bottom: 8px;
  text-align: left;
}

.contact-input {
  flex: 1;
  padding: 14px 16px;
  border: 2px solid #e5e7eb;
  border-radius: 10px;
  font-size: 16px;
  outline: none;
  transition: all 0.2s ease;
  width: 100%;
}

/* RTL support for contact inputs */
.contact-input[dir="rtl"] {
  text-align: right;
  direction: rtl;
}

.contact-input[dir="ltr"] {
  text-align: left;
  direction: ltr;
}

.contact-input:focus {
  border-color: #3b82f6;
  box-shadow: 0 0 0 3px rgba(59, 130, 246, 0.1);
}

.contact-input.error {
  border-color: #dc2626;
  box-shadow: 0 0 0 3px rgba(220, 38, 38, 0.1);
}

.error-message {
  color: #dc2626;
  font-size: 12px;
  margin-top: 4px;
  text-align: left;
  display: block;
}

.step-navigation {
  display: flex;
  justify-content: space-between;
  gap: 10px;
  margin-top: auto;
  /* Push navigation to bottom */
  padding-top: 20px;
  border-top: 1px solid #e5e7eb;
}

/* Acknowledgment Checkbox */
.acknowledgment-checkbox {
  margin-bottom: 20px;
  text-align: left;
  padding-left: 8px;
  /* Indent for checkbox */
}

.checkbox-label {
  display: flex;
  align-items: center;
  cursor: pointer;
  font-size: 16px;
  color: #333;
  user-select: none;
  margin-bottom: 10px;
}

.acknowledgment-input {
  position: absolute;
  opacity: 0;
  cursor: pointer;
  height: 0;
  width: 0;
}

.checkmark {
  height: 24px;
  width: 24px;
  background-color: #eee;
  border: 2px solid #ccc;
  border-radius: 8px;
  margin-right: 12px;
  display: flex;
  align-items: center;
  justify-content: center;
  transition: all 0.2s ease;
  position: relative;
}

.acknowledgment-input:checked~.checkmark {
  background-color: white;
  border-color: #3b82f6;
  border-width: 2px;
}

.checkmark:after {
  content: "";
  position: absolute;
  display: none;
  width: 12px;
  height: 12px;
  background-color: #3b82f6;
  border-radius: 4px;
  transition: all 0.2s ease;
}

.acknowledgment-input:checked~.checkmark:after {
  display: block;
}

.checkbox-text {
  flex: 1;
}

/* Chat Interface */
.chat-interface {
  display: flex;
  flex-direction: column;
  height: 100%;
  min-height: 0;
  /* Allow content to shrink */
  flex: 1;
  /* Take up all available space */
}

.chat-messages {
  flex: 1;
  overflow-y: auto;
  overflow-x: hidden;
  padding-bottom: 10px;
  /* Space for input area */
  min-height: 0;
  /* Allow messages to shrink */
  scroll-behavior: smooth;
  padding-right: 16px;
  padding-left: 16px;
}

.chat-turn {
  display: flex;
  flex-direction: column;
  align-items: stretch;
  gap: 8px;
  width: 100%;
  margin: 0 0 16px;
}
.chat-turn > .message,
.chat-turn > .assis-products-container,
.chat-turn > .assis-checkout-slot,
.chat-container .chat-turn > .assis-message-question,
.chat-container.assis-chat-v2 .chat-turn > .assis-message-question,
.chat-container.assis-chat-v2.assis-chat-he-flip .chat-turn > .assis-message-question,
.chat-turn > .assis-follow-replies,
.chat-turn > .assis-message-question + .assis-follow-replies {
  margin-top: 0;
  margin-bottom: 0;
}
.chat-turn > .assis-products-container {
  padding-top: 0;
  padding-bottom: 0;
}
.chat-turn > .assis-products-container.assis-products-container--carousel .assis-products-track {
  padding-bottom: 4px;
}

.message {
  display: flex;
  margin-bottom: 15px;
  width: 100%;
  animation: slideUpMessage 0.72s cubic-bezier(0.22, 1, 0.36, 1);
}

.message.message-no-animation {
  animation: none !important;
}

.message.message-no-animation .assis-product-card-slot,
.message.message-no-animation .assis-products-container .assis-lh-section-title,
.message.message-no-animation .assis-lh-coupon-card,
.message.message-no-animation .assis-discounts-container .assis-lh-section-title,
.message.message-no-animation .assis-contact-submission {
  animation: none !important;
}

.message.user {
  justify-content: flex-end;
  /* Align user messages to the right */
}

.message.agent,
.message.business,
.message.assis,
.message.ai {
  justify-content: flex-start;
  /* Align agent messages to the left */
}

.message-content {
  display: flex;
  flex-direction: column;
  max-width: 80%;
  overflow: hidden;
}

.agent-info {
  display: flex;
  flex-direction: column;
  gap: 4px;
  align-items: center;
  justify-content: start;
  color: #6b7280;
  font-size: 12px;
  width: 52px;
}

.agent-info-business {
  margin-left: -4px;
}

.agent-avatar {
  width: 24px;
  height: 24px;
  background: #3b83f65a;
  border-radius: 50%;
  display: flex;
  align-items: center;
  justify-content: center;
  width: 28px;
  height: 28px;
}

.agent-name {
  font-weight: 600;
}

.message-bubble {
  padding: 6px 12px;
  border-radius: 15px;
  font-size: 11px !important;
  line-height: 1.6;
  word-break: break-word;
  width: fit-content;
  height: fit-content;
  transition: text-align 0.2s ease;
  word-wrap: break-word;
  overflow-wrap: break-word;
  font-weight: 400;
  font-style: normal;
  text-size-adjust: 100%;
}

.message-text {
  margin: 0;
  padding: 0;
  font-family: inherit;
  font-size: inherit;
  line-height: inherit;
  word-break: break-word;
  overflow-wrap: break-word;
}

.text-white {
  color: white !important;
}

.text-white a {
  color: white !important;
  text-decoration: underline;
}

.text-white a:hover {
  color: rgba(255, 255, 255, 0.8) !important;
}

.message-text strong {
  font-weight: 700;
}

.message-text a {
  color: #3b82f6;
  text-decoration: underline;
}

.message-text a:hover {
  color: #2563eb;
}

.message-bubble a {
  color: #3b82f6;
  text-decoration: underline;
}

.message-bubble a:hover {
  color: #2563eb;
}

.message-bubble strong {
  font-weight: 700;
}

/* Dark mode support */
@media (prefers-color-scheme: dark) {
  .message-text a {
    color: #60a5fa;
  }

  .message-text a:hover {
    color: #3b82f6;
  }

  .message-bubble a {
    color: #60a5fa;
  }

  .message-bubble a:hover {
    color: #3b82f6;
  }
}

/* RTL support for message bubbles */
.message-bubble[dir="rtl"] {
  text-align: right;
  direction: rtl;
}

.message-bubble[dir="ltr"] {
  text-align: left;
  direction: ltr;
}

/* RTL support for message text */
.message-bubble[dir="rtl"] .message-text {
  text-align: right;
  direction: rtl;
}

.message-bubble[dir="ltr"] .message-text {
  text-align: left;
  direction: ltr;
}

.message.sender-client .message-bubble {
  background-color: #3b82f6;
  border-bottom-right-radius: calc(0.5rem - 2px);
  /* Blue for client messages */
  color: white !important;
  border: none;
}

/* RTL message alignment adjustments */
.message.sender-client .message-bubble[dir="rtl"] {
  margin-left: auto;
  margin-right: 0;
}

.message.sender-agent .message-bubble[dir="rtl"],
.message.sender-ai .message-bubble[dir="rtl"],
.message.sender-assis .message-bubble[dir="rtl"],
.message.sender-business .message-bubble[dir="rtl"] {
  margin-right: auto;
  margin-left: 0;
}

.chat-container.assis-chat-v2.assis-chat-he-flip .message:has(.assis-message-question),
.chat-container.assis-chat-v2 .message:has(.assis-message-question) {
  justify-content: stretch;
}
.chat-container.assis-chat-v2.assis-chat-he-flip .message:has(.assis-message-question) .message-content,
.chat-container.assis-chat-v2 .message:has(.assis-message-question) .message-content {
