}

@media (max-width: 767px) {
  .chat-container.assis-chat-v2 .chat-input,
  .chat-container.assis-chat-v2 .chat-input::placeholder,
  .assis-home-input,
  textarea.chat-input {
    font-size: 16px !important;
  }
}

/* Powered launcher is a rounded square, parked on the same corner the scaled heart used. */
.fixed-heart-btn.plan-powered-by-assis {
  transform: none;
  border-radius: 16px;
  background-color: #ffffff;
  overflow: visible;
  box-shadow:
    0 1px 0 rgba(255, 255, 255, 0.9) inset,
    0 8px 18px rgba(148, 163, 184, 0.22),
    0 2px 5px rgba(148, 163, 184, 0.12);
}

.fixed-heart-btn.plan-powered-by-assis.button-small {
  width: 46px;
  height: 46px;
  min-width: 46px;
  max-width: 46px;
  bottom: 44px;
}

.fixed-heart-btn.plan-powered-by-assis.button-small.button-right {
  right: 44px;
  left: auto;
}

.fixed-heart-btn.plan-powered-by-assis.button-small.button-left {
  left: 44px;
  right: auto;
}

.fixed-heart-btn.plan-powered-by-assis.button-medium {
  width: 54px;
  height: 54px;
  min-width: 54px;
  max-width: 54px;
  bottom: 44px;
}

.fixed-heart-btn.plan-powered-by-assis.button-medium.button-right {
  right: 44px;
  left: auto;
}

.fixed-heart-btn.plan-powered-by-assis.button-medium.button-left {
  left: 44px;
  right: auto;
}

.fixed-heart-btn.plan-powered-by-assis.button-large {
  width: 62px;
  height: 62px;
  min-width: 62px;
  max-width: 62px;
  bottom: 40px;
}

.fixed-heart-btn.plan-powered-by-assis.button-large.button-right {
  right: 40px;
  left: auto;
}

.fixed-heart-btn.plan-powered-by-assis.button-large.button-left {
  left: 40px;
  right: auto;
}

.fixed-heart-btn.plan-powered-by-assis .heart-image {
  width: 72%;
  height: 72%;
  max-width: none;
  max-height: none;
  inset: 0;
  margin: auto;
  filter: none;
  transform: none;
}

/* Unread "1" is allowed on Powered too (e.g. with outside bubbles). Vue gates visibility. */

.heart-chat-hint {
  position: absolute;
  top: -18px;
  left: -10px;
  right: auto;
  z-index: 6;
  width: 32px;
  height: 30px;
  display: block;
  background: none;
  pointer-events: none;
  transform-origin: 78% 70%;
  filter: drop-shadow(0 1px 1.5px rgba(29, 111, 238, 0.22));
  animation: assis-chat-nudge 5.6s ease-in-out infinite;
}

.heart-chat-hint__glyph {
  position: relative;
  display: block;
  width: 32px;
  height: 30px;
  background: none;
}

.heart-chat-hint__glyph svg {
  display: block;
  width: 32px;
  height: 30px;
}

@keyframes assis-chat-nudge {
  0%, 74%, 100% { transform: rotate(-28deg) scale(0.70); }
  80% { transform: translate(-1px, -2px) rotate(-34deg) scale(0.70); }
  86% { transform: translate(1px, 0) rotate(-22deg) scale(0.70); }
  92% { transform: rotate(-28deg) scale(0.70); }
}

@media (prefers-reduced-motion: reduce) {
  .heart-chat-hint {
    animation: none;
    transform: rotate(-28deg) scale(0.70);
  }
}

@media (max-width: 767px) {
  .fixed-heart-btn.plan-powered-by-assis,
  .fixed-heart-btn.plan-powered-by-assis.button-small,
  .fixed-heart-btn.plan-powered-by-assis.button-medium,
  .fixed-heart-btn.plan-powered-by-assis.button-large {
    width: 46px;
    height: 46px;
    min-width: 46px;
    max-width: 46px;
    bottom: max(16px, env(safe-area-inset-bottom));
    overflow: visible;
  }

  .fixed-heart-btn.plan-powered-by-assis.button-small.button-right,
  .fixed-heart-btn.plan-powered-by-assis.button-medium.button-right,
  .fixed-heart-btn.plan-powered-by-assis.button-large.button-right,
  .fixed-heart-btn.plan-powered-by-assis.button-right {
    right: max(16px, env(safe-area-inset-right));
    left: auto;
  }

